def write(name, header, rows):
    p = out_dir / name
    with p.open("w", encoding="utf-8", newline="") as f:
        w = csv.writer(f, lineterminator="\n")
        w.writerow(header)
        for r in rows:
            assert len(r) == len(header), (name, r[2], len(r), len(header))
            w.writerow(r)
    print("written", p, len(rows), "rows")

write("IOND SDLC - DISCOVERY.csv", HDR_KANBAN, discovery)
write("IOND SDLC - IMPROVEMENTS.csv", HDR_KANBAN, improvements)
write("IOND SDLC - RELEASES.csv", HDR_RELEASE, releases)
